import json,os
from urllib.parse import urlparse
hits=[]
for l in open('data/cdx/avail.jsonl'):
    r=json.loads(l)
    if r['verdict']=='hit': hits.append(r)
# map normalized url -> post records
import collections
recs=[]
for fn in os.listdir('data/posts'):
    recs.append(json.load(open('data/posts/'+fn)))
def norm(u):
    p=urlparse(u)
    return (p.netloc+p.path).lower()
for h in hits:
    k=norm(h['url'])
    found=[]
    for r in recs:
        for im in r.get('images') or []:
            urls=[im.get('media_url','')]+[v for v in (im.get('variants') or [])]
            if any(norm(u)==k for u in urls):
                found.append((r['post_id'], im.get('state'), im.get('error'), im.get('sha256') is not None))
    print(h['url'], h['timestamp'], '->', found)
EOF

