import json,os,re,collections
posts={}
for f in os.listdir('data/posts'):
    posts[f[:-5]]=json.load(open('data/posts/'+f))
print("posts",len(posts))
hostpat=re.compile(r'//(\d+)\.media\.tumblr\.com/([0-9a-f]{16,})/')
cat=collections.Counter()
cand={}
for pid,p in posts.items():
    imgs=p.get('images') or []
    for im in imgs:
        u=im.get('media_url') or ''
        m=hostpat.search(u)
        h=m.group(1) if m else ('hashed' if re.search(r'//[a-z0-9-]+\.media\.tumblr\.com/[0-9a-f]{16,}/',u) else 'plain')
        rec=im.get('sha256')
        cat[(h, 'recovered' if rec else 'missing')]+=1
        if not rec:
            cand.setdefault(h,[]).append((pid,u))
for k,v in sorted(cat.items()):
    print(k,v)
print()
for h in sorted(cand, key=lambda x:(len(x),x)):
    print(h, len(cand[h]), cand[h][0])
EOF

