import json, os, re, collections
posts={}
for fn in os.listdir('data/posts'):
    if fn.endswith('.json'):
        p=json.load(open('data/posts/'+fn))
        posts[str(p.get('post_id'))]=p

stems={}
for line in open('data/cdx/stems.jsonl'):
    line=line.strip()
    if not line: continue
    r=json.loads(line)
    stems[r['stem']]=r

def stem_of(u):
    if not u: return None
    m=re.match(r'^(https?://[^/]+/[^/]+/tumblr_[A-Za-z0-9]+)', u)
    if m: return m.group(1)
    m=re.match(r'^(https?://[^/]+/tumblr_[A-Za-z0-9]+)', u)
    return m.group(1) if m else None

stats=collections.Counter()
unanswered=collections.Counter()
hit_not_recovered=[]
for pid,p in posts.items():
    for im in p.get('images') or []:
        u=im.get('media_url') or im.get('url')
        st=stem_of(u)
        state=im.get('state')
        if st is None:
            stats['no_stem']+=1
            continue
        if st not in stems:
            stats['stem_unanswered']+=1
            unanswered[st]+=1
            continue
        r=stems[st]
        if r.get('captures'):
            stats['stem_hit']+=1
            if state!='recovered':
                hit_not_recovered.append((pid,st,state,im.get('error'),len(r['captures'])))
        else:
            stats['stem_empty']+=1
            if state=='recovered':
                stats['recovered_despite_empty']+=1
print(stats)
print('unanswered stems:', len(unanswered))
print('hit but not recovered:', len(hit_not_recovered))
for x in hit_not_recovered[:30]: print('  ',x)
EOF

