import json,glob,collections,os
# unique sha256 from verification files (role media)
vsha=collections.defaultdict(set)
for f in glob.glob('data/verification/*.json'):
    d=json.load(open(f))
    for pf in d.get('pulled_files') or []:
        if pf.get('role')=='media' and pf.get('sha256'):
            vsha[pf['sha256']].add(str(d.get('post_id')))
print('verification files',len(glob.glob('data/verification/*.json')),'unique media sha256',len(vsha))
# recovered in posts
rec={}
for f in glob.glob('data/posts/*.json'):
    d=json.load(open(f))
    for im in d.get('images') or []:
        if im.get('sha256'): rec[im['sha256']]=(str(d.get('post_id')),im.get('file'))
print('posts unique recovered sha256',len(rec))
# published image tags
mx={}
for line in open('data/published.jsonl'):
    line=line.strip()
    if not line: continue
    r=json.loads(line)
    pid=str(r.get('post_id')); ic=r.get('image_count',0) or 0
    if pid not in mx or ic>mx[pid]: mx[pid]=ic
pubimg={p for p,c in mx.items() if c>0}
# posts with recovered bytes but no published image tag
unpub=[]
for sha,(pid,file) in rec.items():
    if pid not in pubimg: unpub.append((pid,file,sha))
print('recovered but post not in published image tags:',len(unpub))
for u in unpub[:20]: print('  ',u)
# verification media hashes not in posts rec
missing_in_posts=set(vsha)-set(rec)
print('verification hashes not in current post records:',len(missing_in_posts))
