import json,os,collections
d='data/posts'
hashpost=collections.defaultdict(set)
for f in os.listdir(d):
    try: p=json.load(open(os.path.join(d,f)))
    except: continue
    pid=p.get('post_id')
    for im in p.get('images') or []:
        if im.get('sha256'):
            hashpost[im['sha256']].add(pid)
dups={h:sorted(v) for h,v in hashpost.items() if len(v)>1}
print('hashes in >1 post:',dups)
# within-post duplicate hashes
for f in os.listdir(d):
    try: p=json.load(open(os.path.join(d,f)))
    except: continue
    hs=[im['sha256'] for im in (p.get('images') or []) if im.get('sha256')]
    c=collections.Counter(hs)
    dd={k:v for k,v in c.items() if v>1}
    if dd: print('within-post dup',p['post_id'],dd)
EOF

