cd /tmp/shurik-workspace-Bybd8P && python3 - <<'EOF'
import json,glob,collections
from recovery.images import stem_prefix
from recovery.cdx import normalize_url
stems={}
for line in open('data/cdx/stems.jsonl'):
    line=line.strip()
    if not line: continue
    try: r=json.loads(line)
    except: continue
    stems[r.get('key')]=r
posts={}
for p in glob.glob('data/posts/*.json'):
    d=json.load(open(p)); posts[str(d.get('post_id'))]=d
multi=0; total=0; opps=[]
for pid,d in posts.items():
    stored=set()
    for im in d.get('images') or []:
        if im.get('state')=='recovered' and im.get('media_url'):
            stored.add(normalize_url(im.get('media_url')))
    if not stored: continue
    for im in d.get('images') or []:
        if im.get('state')!='recovered': continue
        u=im.get('media_url') or ''
        stem=stem_prefix(u)
        row=stems.get(normalize_url(stem)) or stems.get(stem)
        total+=1
        if not row: continue
        caps=[c for c in row.get('captures') or [] if c.get('statuscode')=='200']
        urls={normalize_url(c.get('original','')) for c in caps}
        new=urls-stored
        if len(caps)>1 or new:
            multi+=1
            opps.append((pid,u,sorted(urls),sorted(stored)))
print('recovered entries',total,'with multi captures in stem',multi)
for o in opps[:25]: print(o[0],o[1][:70],'\n   stem urls:',[x[:80] for x in o[2]],'\n   stored:',[x[:80] for x in o[3]])
EOF

