import json, glob, re
from recovery.parsing import is_tumblr_media, media_key, is_excluded_image
from recovery.images import stem_prefix
from recovery.stemindex import StemIndex
idx=StemIndex()
amp=re.compile(r'<amp-img\b[^>]*>',re.I)
src=re.compile(r'''(?:^|\s)(?:src|data-src)\s*=\s*["']([^"']+)''',re.I)
srcset=re.compile(r'''(?:^|\s)(?:srcset|data-srcset)\s*=\s*["']([^"']+)''',re.I)
rows=[]
for f in glob.glob('data/posts/*.json'):
    d=json.load(open(f))
    html=d.get('content_html') or ''
    if '<amp-img' not in html.lower(): continue
    have=set()
    for img in d.get('images') or []:
        for u in (img.get('url_forms') or [img.get('media_url')]):
            if u: have.add(media_key(u))
    got={}
    for tag in amp.findall(html):
        urls=[]
        m=src.search(tag)
        if m: urls.append(m.group(1))
        for m in srcset.findall(tag):
            for part in m.split(','):
                u=part.strip().split(' ')[0]
                if u: urls.append(u)
        for u in urls:
            u=u.replace('&amp;','&')
            if not u.lower().startswith(('http://','https://')): continue
            if not is_tumblr_media(u) or is_excluded_image(u): continue
            k=media_key(u)
            if k and k not in have:
                got.setdefault(k,u)
