from recovery.store import PostStore
from recovery.stemindex import StemIndex
from recovery.images import stem_prefix
idx=StemIndex()
missing=set()
for rec in PostStore().all():
    for img in rec.get('images') or []:
        if img.get('sha256'): continue
        for form in [img.get('media_url')]+list(img.get('url_forms') or []):
            if not form: continue
            s=stem_prefix(form)
            if not idx.has(s): missing.add(s)
print("unknown stems for unresolved images:",len(missing))
for s in sorted(missing)[:30]: print("  ",s)
