arguments.command:
cd "$(git rev-parse --show-toplevel)" && python3 - <<'EOF'
import json,glob,os,hashlib
hashes={}
posts_with=set()
for f in glob.glob('data/posts/*.json'):
    pid=os.path.basename(f)[:-5]
    try: d=json.load(open(f))
    except: continue
    for i in d.get('images') or []:
        if i.get('sha256'):
            hashes.setdefault(i['sha256'],[]).append(pid)
            posts_with.add(pid)
print("unique sha256:",len(hashes))
print("posts with recovered:",len(posts_with))
# duplicates
dups={h:p for h,p in hashes.items() if len(p)>1}
print("hashes with multiple posts:",len(dups))
for h,p in list(dups.items())[:20]: print(h[:12],p)
EOF

