cd "$(git rev-parse --show-toplevel)" && python3 - <<'EOF'
import json,glob,os,re,sys
sys.path.insert(0,'.')
from recovery.parsing import stem_prefix
# load stem index keys
keys=set()
for line in open('data/cdx/stems.jsonl'):
    line=line.strip()
    if not line: continue
    r=json.loads(line)
    keys.add(r['stem'])
    if r['stem'].startswith('http://'):
        keys.add('https://'+r['stem'][7:])
    elif r['stem'].startswith('https://'):
        keys.add('http://'+r['stem'][8:])
unresolved_stems={}
for f in glob.glob('data/posts/*.json'):
    pid=os.path.basename(f)[:-5]
    try: d=json.load(open(f))
    except: continue
    for i in d.get('images') or []:
        if i.get('sha256'): continue
        forms=[i.get('media_url') or '']+list(i.get('url_forms') or [])
        for u in forms:
            s=stem_prefix(u)
            if s: unresolved_stems.setdefault(s,set()).add(pid)
print("distinct unresolved stems:",len(unresolved_stems))
missing=[s for s in unresolved_stems if s not in keys]
print("unresolved stems NOT in stem index:",len(missing))
for s in missing[:40]: print(s, sorted(unresolved_stems[s])[:3])
EOF

