    posts[d['post_id']]=d

def stemkey(u):
    m=re.match(r'https?://([^/]+)/(.+?)(?:_\d+)?\.(jpg|jpeg|png|gif)$', u or '')
    if not m: return None
    return f"{m.group(1)}/{m.group(2)}"

# Build index of posts by image stem key
key2posts={}
for pid,d in posts.items():
    for i in d.get('images',[]):
        k=stemkey(i.get('media_url'))
