def host_of(url: str) -> str:
    m = re.match(r"^https?://([^/]+)", url or "", re.I)
    return m.group(1).lower() if m else ""


def key_of(url: str) -> str:
    """Lowercase identity of a media file, ignoring size suffix and extension."""
    base = base_media_key(url) or media_key(url) or os.path.basename(normalize_url(url))
    base = base.lower()
    stem, _, ext = base.rpartition(".")
    return stem + "." + ext if ext else stem


def stems_of(url: str) -> set[str]:
    """Every key a media file could be indexed under (all size variants)."""
    keys = {key_of(v) for v in parse_image_variants(url)}
    keys.add(key_of(url))
    return {k for k in keys if k}


class MediaIndex:
    """Local, durable index of archived media captures keyed by media file."""

    def __init__(self, path: str = ""):
        # Late-bound on purpose: see PostStore.__init__ (import-time defaults
        # would pin the committed data/cdx/media.jsonl into every caller).
        self.index = CaptureIndex(path or os.path.join(config.CDX_DIR, "media.jsonl"))
        self._by_url: dict[str, list[Capture]] = {}
        self._by_key: dict[str, list[Capture]] = {}
        for cap in self.index.all():
            self._remember(cap)
        # Older runs wrote the manifest key as `host:host:<h>`, so every scan
        # looked unfinished and got re-requested from page 1 forever.
        self.hosts_done()

    def _remember(self, cap: Capture) -> None:
        self._by_url.setdefault(normalize_url(cap.original), []).append(cap)
        self._by_key.setdefault(key_of(cap.original), []).append(cap)

    def add(self, captures: Iterable[Capture]) -> int:
        caps = list(captures)
        new = self.index.add(caps)
        for cap in caps:
            self._remember(cap)
        return new

    def lookup(self, url: str) -> list[Capture]:
        """Captures for a media URL: exact match first, then any variant."""
        exact = self._by_url.get(normalize_url(url), [])
        if exact:
            return sorted(exact, key=lambda c: c.timestamp)
        out: list[Capture] = []
        for key in stems_of(url):
            out.extend(self._by_key.get(key, []))
        # Same media file on another CDN host is still evidence of the image.
        if not out:
            for key in stems_of(url):
                for cap_url, caps in self._by_key.items():
                    if key in cap_url:
                        out.extend(caps)
        seen: set[str] = set()
        uniq = []
        for cap in sorted(out, key=lambda c: c.timestamp):
            if cap.key in seen:
                continue
            seen.add(cap.key)
            uniq.append(cap)
        return uniq

    def __len__(self) -> int:
        return len(self.index.all())

    def hosts_done(self) -> dict:
        """Manifest `done` map, with legacy `host:host:<h>` keys repaired.

        The repair matters for more than tidiness: a host whose scan reached its
        last page is *positive evidence* that its pre-cutoff 200 rows have all
        been seen. With the key spelled wrongly that evidence was invisible, so
        every run re-downloaded completed hosts (archive load) and never let the
        crawler record a confirmed per-host gap.
        """
        done = self.index.manifest.setdefault("done", {})
        stale = [k for k in done if k.startswith("host:host:")]
        for key in stale:
            done[key[len("host:"):]] = done.pop(key)
        if stale:
            self.index.save_manifest()

    answered = [a for a in record.get("attempts") or []
