    "40.media.tumblr.com", "41.media.tumblr.com", "64.media.tumblr.com",
    "65.media.tumblr.com", "66.media.tumblr.com", "67.media.tumblr.com",
    "68.media.tumblr.com", "78.media.tumblr.com", "media.tumblr.com",
)

