    kinds = {"perm": 0, "amp": 1, "photoset": 2, "other": 3}
    grouped: dict[str, list[Capture]] = {}
    for cap in index.all():
        url = normalize_url(cap.original)
        m = POST_ID_RE.search("/" + url.split("/", 1)[1] if "/" in url else url)
        if not m:
            continue
        if cap.statuscode not in ("200", ""):
            continue
