# --------------------------------------------------------------------- discover
def discover_posts(fetcher: Fetcher, years: Optional[list[str]] = None, force: bool = False) -> dict:
    """Resumable CDX inventory of /post/* captures (year windows).

    NOTE: the CDX `prefix` match type must not be combined with a `*` suffix;
    `url=hazfalafel.com/post/*&matchType=prefix` returns `[]` while
    `url=hazfalafel.com/post/&matchType=prefix` returns every post capture.
    """
    index = CaptureIndex(capture_file("posts.jsonl"))
    stats = {"new": 0, "queries": 0, "skipped": 0}
    for start in (years or year_windows()):
        name = f"posts:{start}"
        if index.query_done(name) and not force:
            stats["skipped"] += 1
            continue
        params_year = start[:4]
        caps, resp = _cdx_window(fetcher, POST_CAPTURE_PREFIX, params_year)
        stats["queries"] += 1
        new = index.add(caps)
        stats["new"] += new
        info = {"captures": len(caps), "new": new, "response_error": resp.error,
                "status": resp.status, "message": resp.message[:200]}
        if resp.ok:
            index.mark_done(name, info)
        else:
            # A failed request is not a "no captures" answer. Leave the window
            # retryable instead of settling it (see CaptureIndex.mark_failed).
            index.mark_failed(name, info)
            stats.setdefault("failed", []).append(name)
    return {**stats, "total": len(index.all())}


def discover_listings(fetcher: Fetcher, force: bool = False) -> dict:
    """Archive/tag/monthly pages: discovery leads for posts without permalinks."""
    index = CaptureIndex(capture_file("listing.jsonl"))
    stats = {"new": 0, "queries": 0, "skipped": 0}
    for prefix in ("hazfalafel.com/archive/", "hazfalafel.com/tagged/",
                   POST_CAPTURE_PREFIX, *EXTRA_LISTING_PREFIXES):
        name = f"listing:{prefix}"
        if index.query_done(name) and not force:
            stats["skipped"] += 1
            continue
        caps, resp = cdx_query(fetcher, prefix, match="prefix", limit=20000)
        stats["queries"] += 1
        stats["new"] += index.add(caps)
        info = {"captures": len(caps), "response_error": resp.error, "status": resp.status}
        if resp.ok:
            index.mark_done(name, info)
        else:
            index.mark_failed(name, info)
            stats.setdefault("failed", []).append(name)

def host_of(url: str) -> str:
    try:
        return (urlparse(url if "//" in url else "http://" + url).hostname or "").lower()
    except Exception:
        return ""


def is_tumblr_media(url: str) -> bool:
    return bool(re.search(config.MEDIA_HOST_RE, host_of(url)))


def media_key(url: str) -> Optional[str]:
    """tumblr_<name> plus size/extension: the identity of one Tumblr media file."""
    path = urlparse(url).path
    m = MEDIA_PATH_RE.search(path)
    if not m:
        return None
    return m.group(1) + "." + m.group(2).lower()


def base_media_key(url: str) -> Optional[str]:
    """Identity ignoring the size suffix (_500, _1280, ...)."""
    key = media_key(url)
    if not key:
        return None
    stem, _, ext = key.rpartition(".")
    stem = re.sub(r"_\d{2,4}$", "", stem)
    return stem + "." + ext


def is_excluded_image(url: str, attrs: str = "") -> Optional[str]:
    low = (url or "").lower()
    if not low:
        return "empty-src"
    if "avatar" in low or "default_avatar" in low:
        return "avatar"
    for hint in EXCLUDE_IMG_HINTS:
        if hint in low:
            return "excluded:" + hint
    if re.search(r'\bwidth="1"', attrs) and re.search(r'\bheight="1"', attrs):
        return "tracking-pixel"
    return None


VARIANT_RE = re.compile(
    r"^(?P<stem>(?:tumblr_)?[^_/?#]+(?:_[A-Za-z0-9]+)*?)_(?P<size>\d{2,4})\."
    r"(?P<ext>jpg|jpeg|png|gif|webp)$", re.I)


def parse_image_variants(url: str) -> list[str]:
    """Candidate archived variants for one Tumblr media file (larger first).

    Wayback frequently holds a *different* size of the same file (`_540` when
    the page linked `_500`), so every size and extension sibling is a real
    recovery lead. The match runs on the URL path *basename*: matching the
    whole path silently found nothing because paths start with `/`.
    """
    out = [url]
    path = urlparse(url).path
    m = VARIANT_RE.match(path.rsplit("/", 1)[-1])
    if not m:
        return out
    stem, ext = m.group("stem"), m.group("ext")
    # Slice on the *full* URL, not on urlparse().path: the path index does not
    # line up with the URL string once a scheme and host are in front of it.
    head = url.split("#", 1)[0].split("?", 1)[0]
    base = head[: head.rfind("/") + 1]
    for size in ("1280", "1024", "540", "500", "400", "250", "100"):
        cand = f"{base}{stem}_{size}.{ext}"
        if cand not in out:
            out.append(cand)
    for alt_ext in ("png", "gif", "jpg"):
        if alt_ext == ext.lower():
            continue
        cand = f"{base}{stem}.{alt_ext}"
        if cand not in out:
            out.append(cand)
    return out


