cd /tmp/shurik-workspace-H7ixeM && python3 - <<'EOF'
import json,collections,re
from recovery.listing import listing_kind
from recovery.cli import _listing_done_keys
from recovery.cdx import normalize_url
ev=[]
with open('data/cdx/listing-posts.jsonl') as f:
    for line in f:
        line=line.strip()
        if line:
            try: ev.append(json.loads(line))
            except: pass
done=_listing_done_keys(ev)
caps=[]
with open('data/cdx/listing.jsonl') as f:
    for line in f:
        line=line.strip()
        if line:
            try: caps.append(json.loads(line))
            except: pass
samples=collections.defaultdict(list)
for c in caps:
    k=f"{c['timestamp']}|{normalize_url(c['original'])}"
    if k in done: continue
    kd=listing_kind(c['original'])
    if len(samples[kd])<15: samples[kd].append(c['original'])
for k,v in samples.items():
    print("==",k)
    for u in v: print("  ",u)
EOF

