import json,os,collections
from recovery.listing import listing_kind
from recovery.cli import _listing_done_keys
from recovery.cdx import normalize_url
from recovery.parsing import post_id_from_url
ev=[]
for line in open('data/cdx/listing-posts.jsonl'):
    line=line.strip()
    if line:
        try: ev.append(json.loads(line))
        except: pass
done=_listing_done_keys(ev)
caps=[]
for line in open('data/cdx/listing.jsonl'):
    line=line.strip()
    if line:
        try: caps.append(json.loads(line))
        except: pass
pend_urls=collections.defaultdict(set)
for c in caps:
    k=f"{c['timestamp']}|{normalize_url(c['original'])}"
    if k in done: continue
    pend_urls[listing_kind(c['original'])].add(normalize_url(c['original']))
have=set(f[:-5] for f in os.listdir('data/posts') if f.endswith('.json'))
missing=[];present=0
for u in pend_urls['post_other']:
    pid=post_id_from_url(u)
    if pid and pid in have: present+=1
    else: missing.append((u,pid))
print("post_other distinct:",len(pend_urls['post_other']),"parsed-present:",present,"not-parsed:",len(missing))
for u,pid in missing[:15]: print("   ",u,"->",pid)
print("other distinct:",len(pend_urls['other']))
for u in sorted(pend_urls['other'])[:20]: print("   other:",u)
print("archive distinct:",len(pend_urls['archive']))
EOF

cd /tmp/shurik-workspace-H7ixeM && python3 - <<'EOF'
import json,os
pub={}
for line in open('data/published.jsonl'):
    line=line.strip()
    if not line: continue
    try: d=json.loads(line)
    except: continue
    pid=str(d.get('post_id') or d.get('tag'))
    pub[pid]=max(pub.get(pid,0),d.get('image_count',0))
pend=[]
for fn in os.listdir('data/posts'):
    if not fn.endswith('.json'): continue
    pid=fn[:-5]
    try: d=json.load(open('data/posts/'+fn))
    except: continue
    keys=set(); resolved_keys=set()
    for im in d.get('images') or []:
        k=im.get('media_key') or (im.get('url_forms') or [None])[0]
        if k: keys.add(k)
        if im.get('sha256') and k: resolved_keys.add(k)
    p=pub.get(pid,0)
    if len(resolved_keys)>p:
        pend.append((pid,len(resolved_keys),p,d.get('image_count'),len(keys)))
print("pending publication (distinct resolved media keys > published):",len(pend))
for r in pend: print(r)
EOF

