import json,re
ids={'163370157578','166664090817','167900697613','169500211728','179747742778','180044590448','180273035943','180352733148','181548335348','181548463263'}
found={}
for l in open('data/cdx/posts.jsonl'):
    try:r=json.loads(l)
    except:continue
    m=re.search(r'/post/(\d+)',r.get('original') or '')
    if m and m.group(1) in ids:
        found.setdefault(m.group(1),[]).append((r['timestamp'],r['original']))
for i in sorted(ids):
    print(i, found.get(i))
# also check listing evidence
print("--- listing-posts ---")
for l in open('data/cdx/listing-posts.jsonl'):
    try:r=json.loads(l)
    except:continue
    s=json.dumps(r)
    for i in ids:
        if i in s:
            print(i, r.get('post_id'), r.get('post_other'), r.get('listing_url'), (r.get('media_url') or '')[:80]); break
EOF

