import json
from recovery.images import stem_prefix
from recovery.stemindex import StemIndex
from recovery.store import PostStore
from recovery.parsing import base_media_key
si=StemIndex()
forms=set()
for l in open('data/cdx/listing-posts.jsonl'):
    try:r=json.loads(l)
    except:continue
    ims=r.get('images')
    if not isinstance(ims,list): continue
    for im in ims:
        if not isinstance(im,dict): continue
        u=im.get('media_url')
        if u: forms.add(u)
        for f in im.get('url_forms') or []: forms.add(f)
unasked=[u for u in forms if not si.has(stem_prefix(u))]
print("unasked forms:",len(unasked))
store=PostStore()
unres_base={}
for rec in store.all():
    for img in rec.get('images') or []:
        if img.get('sha256'): continue
        for f in [img.get('media_url') or '']+(img.get('url_forms') or []):
            if not f: continue
            b=base_media_key(f)
            if b: unres_base.setdefault(b,[]).append((rec['post_id'],img.get('media_url'),f))
rel=[]
for u in unasked:
    b=base_media_key(u)
    if b and b in unres_base:
        rel.append((u,unres_base[b]))
print("unasked forms whose base key matches an unresolved store image:",len(rel))
seen=set()
for u,matches in rel:
    if u in seen: continue
    seen.add(u)
    print("  ",u)
    for m in matches[:2]: print("       ->",m)
