import json,glob,re,collections
# keys in post records
postkeys=set(); postforms=collections.defaultdict(set)
for fp in glob.glob('data/posts/*.json'):
    p=json.load(open(fp))
    for im in p.get('images') or []:
        u=im.get('media_url') or ''
        m=re.search(r'(tumblr_[A-Za-z0-9]+)',u)
        if m: postkeys.add(m.group(1))
        for f in [u]+(im.get('url_forms') or []):
            if m: postforms[m.group(1)].add(f)
# unassigned listing keys + their urls
unassigned={}
for line in open('data/cdx/listing-posts.jsonl'):
    r=json.loads(line)
    imgs=r.get('images')
    if not isinstance(imgs,list): continue
    if r.get('post_id'): continue
    for im in imgs:
        if not isinstance(im,dict): continue
        k=im.get('media_key')
        if k: unassigned.setdefault(re.sub(r'_\d+\.\w+$','',k), []).append(im.get('media_url'))
base_un=set(unassigned)
