# map to tumblr_ keys
def key_of(u):
    m=re.search(r'(tumblr_[A-Za-z0-9]+)',u or '')
    return m.group(1) if m else None
unk=[k for k in base_un if key_of(k) not in postkeys]
print('unassigned keys NOT in post records:',len(unk))
for k in list(unk)[:30]:
