def write_cursor(host: str, rec: dict) -> None:
    _, cur = dump_paths(host)
    os.makedirs(CURSOR_DIR, exist_ok=True)
    rec = dict(rec)
    rec["host"] = host.strip().lower()
    rec["scope"] = SCOPE
