def _dump_line_count(path: str) -> int:
    """Non-empty lines in a dump file, or -1 when the file is absent."""
    if not os.path.exists(path):
        return -1
    n = 0
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            if line.strip():
                n += 1
    return n

