    for c in r.get('checks') or []:
        if c.get('check','').startswith('image_bytes') and c.get('passed'):
            e=str(c.get('expected') or '')
            if re.fullmatch(r'[0-9a-f]{64}', e): hs.add(e)
    ver[str(r.get('post_id'))]=hs
allhash=set(h for hs in rec.values() for h in hs)
verified=set(h for hs in ver.values() for h in hs)
print("recovered posts",len(rec),"verified posts",len(ver))
print("recovered hashes",len(allhash),"verified hashes",len(verified))
print("recovered but unverified hashes",len(allhash-verified))
nover=[p for p in rec if p not in ver]
print("recovered posts with NO passing verification:",len(nover),nover)
# posts where recovered set not subset of verified
partial=[]
for p,hs in rec.items():
    vs=ver.get(p,set())
    if not set(hs)<=vs:
        partial.append((p,len(hs),len(vs)))
print("posts with some unverified recovered image:",len(partial))
for x in partial[:40]: print("  ",x)
