si=StemIndex()
pos={k:v for k,v in si.rows.items() if v}

# Build set of all media_urls known from posts (images and missing)
known=set()
recovered_urls=set()
for f in glob.glob('data/posts/*.json'):
    r=json.load(open(f))
    for img in (r.get('images') or []):
        u=img.get('media_url') or img.get('url')
        if u: known.add(u); recovered_urls.add(u)
    for mi in (r.get('missing_images') or []):
        u=mi.get('media_url')
        if u: known.add(u)

# positive stems not matching any known post media url
unmatched=[]
for st,caps in pos.items():
    # check if any known url startswith st
    hit=[u for u in known if u.startswith(st.replace('https://','http://')) or u.replace('https://','http://').startswith(st)]
    if not hit:
        unmatched.append((st,[c.original for c in caps]))
print('positive stems with no known post url:', len(unmatched))
for u in unmatched[:30]: print(u)
