import json,glob,re
from urllib.parse import urlparse
SHARDS=["24","25","26","27","28","29","30","31","33","36","37","38","40","41","64","65","66","67","68","78"]
hits=set()
for line in open('data/cdx/stems.jsonl'):
    r=json.loads(line)
    if r.get('captures'): hits.add(r['key'])
# also index by path (host-independent)
hitpaths={}
for line in open('data/cdx/stems.jsonl'):
    r=json.loads(line)
    if r.get('captures'):
        p=urlparse(r['stem']).path  # /md5dir/tumblr_key
        hitpaths.setdefault(p,[]).append(r)
def stem_prefix(url):
    p=urlparse(url).path
    m=re.match(r'^(.*?/)?((?:tumblr_)?[^_/?#]+(?:_[A-Za-z0-9]+)*?)(?:_\d{2,4})?\.(jpg|jpeg|png|gif|webp)$', p.rsplit('/',1)[-1], re.I)
    if not m: return None
    d=urlparse(url)
    directory=p[:p.rfind('/')+1]
    stemname=m.group(2)
    return f"{d.scheme}://{d.netloc}{directory}{stemname}"
def path_of_stem(s):
    return urlparse(s).path
# collect candidate posts
benef=[]
for f in glob.glob('data/posts/*.json'):
    r=json.load(open(f))
    imgs=r.get('images') or []
    has_rec=any(i.get('sha256') for i in imgs)
    if has_rec: continue
    forms=set()
    for i in imgs:
        for u in [i.get('media_url') or '']+(i.get('url_forms') or []):
            if not u: continue
            sp=stem_prefix(u)
            if not sp: continue
            forms.add(sp)
    # alternate shard variants: same path, different host
    newhits=set()
    for sp in forms:
        pth=path_of_stem(sp)
        if pth in hitpaths:
            for h in hitpaths[pth]:
                if h['stem'] not in forms:
                    newhits.add(h['stem'])
    if newhits:
        benef.append((r['post_id'],len(imgs),sorted(newhits)[:3]))
print("unrecovered posts that would be selected by cross-shard stem hits:",len(benef))
for b in benef: print(b)
EOF

