def listing_kind(original_url: str) -> str:
    """Which listing family a captured URL belongs to."""
    u = (original_url or "").lower()
    if "/archive/" in u:
        return "archive"
    if "/tagged/" in u:
        return "tagged"
    if "/post/" in u:
        return "post_other"
    return "other"


def merge_listing_evidence(record: dict, evidences: list[dict]) -> dict:
    """Fold listing-page evidence into a post record without losing anything.

    * an image whose media key the record already knows is only *added as
      another URL form* -- it is the same photo, so the image count (and the
      "is this post complete" verdict) must not change;
    * an image with a new key becomes a real unresolved image entry, because a
      second photo of the post genuinely was referenced by the archive;
    * a post that only listing pages prove to exist is created with
      `state="listing_only"` and never marked recovered.
    """
    out = dict(record or {})
    images = [dict(i) for i in (out.get("images") or [])]
    by_key = {i.get("media_key"): i for i in images if i.get("media_key")}
    added = 0
    merged_forms = 0
    for ev in evidences:
        for img in ev.get("images") or []:
            key = img.get("media_key")
            have = by_key.get(key)

def xshard_scan(fetcher: Fetcher, *, hosts: Optional[list[str]] = None,
                limit: int = 2000, rescan: bool = False,
                apply: bool = True) -> dict:
    hosts = hosts or list(DEFAULT_HOSTS)
    state = _load_host_state()
    store = PostStore() if apply else None
    out = {"hosts": [], "requests_sent": 0, "found": 0, "applied": 0,
           "scanned": 0, "skipped_done": 0, "failed": 0}
    for host in hosts:
        prev = state.get(host) or {}
        if prev.get("done") and not rescan:
            out["skipped_done"] += 1
            continue
        caps, diag = scan_host(fetcher, host, limit=limit)
        out["requests_sent"] += 1
        out["scanned"] += 1
        if diag.get("error"):
            out["failed"] += 1
            state[host] = {"done": False, "error": diag.get("error"),
                           "status": diag.get("status"), "at": _now()}
            out["hosts"].append(diag)
            _save_host_state(state)
            continue
        append_found(caps, {"host": host})
        out["found"] += len(caps)
        applied = apply_captures(store, caps) if apply else {"added_forms": 0}
        out["applied"] += applied.get("added_forms", 0)
        state[host] = {"done": True, "rows": len(caps), "at": _now(),
                       "applied": applied.get("added_forms", 0)}
        out["hosts"].append({**diag, "applied": applied})
        _save_host_state(state)
    out["pending_hosts"] = [h for h in hosts if not (state.get(h) or {}).get("done")]
    return out


def _now() -> str:
    import time
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

