"""CDX inventory helpers: resumable, cutoff-bounded capture discovery."""
from __future__ import annotations

import json
import os
from dataclasses import dataclass, asdict
from typing import Iterable, Optional

from . import config
from .http import GAP, OK, Fetcher, Response

DEFAULT_FIELDS = "urlkey,timestamp,original,mimetype,statuscode,digest,length,redirect"


@dataclass
class Capture:
    timestamp: str
    original: str
    statuscode: str = ""
    mimetype: str = ""
    digest: str = ""
    length: str = ""
    urlkey: str = ""
    redirect: str = ""
    source_query: str = ""

    @property
    def key(self) -> str:
        return f"{self.timestamp}|{normalize_url(self.original)}"

    def to_row(self) -> dict:
        d = asdict(self)
        return {k: v for k, v in d.items() if v}


def normalize_url(url: str) -> str:
    """Canonical comparison form: no scheme, no default port, lowercase host."""
    u = url.strip()
    for scheme in ("https://", "http://"):
        if u.lower().startswith(scheme):
            u = u[len(scheme):]
            break
    if u.startswith("//"):
        u = u[2:]
    host, _, path = u.partition("/")
    host = host.lower()
    if ":" in host:
        host = host.rsplit(":", 1)[0]
    path = path or "/"
    return f"{host}/{path}" if path != "/" else host


def within_cutoff(timestamp: str, cutoff: str = config.CUTOFF) -> bool:
    return isinstance(timestamp, str) and len(timestamp) >= 14 and timestamp <= cutoff


def parse_cdx_json(rows: list, source_query: str = "") -> list[Capture]:
    """CDX json output: first row is a header when fields are requested."""
    out: list[Capture] = []
    if not rows:
        return out
    header: Optional[list] = None
    first = rows[0]
    if first and isinstance(first[0], str) and first[0] in ("urlkey", "timestamp"):
        header = list(first)
        rows = rows[1:]
    for row in rows:
        if not isinstance(row, (list, tuple)) or not row:
            continue
        if header is None:
            header = DEFAULT_FIELDS.split(",")
            header = header[: len(row)]
        rec = dict(zip(header, [str(v) for v in row]))
        ts = rec.get("timestamp", "")
        if not within_cutoff(ts):
            continue
        out.append(
            Capture(
                timestamp=ts,
                original=rec.get("original", ""),
                statuscode=rec.get("statuscode", ""),
                mimetype=rec.get("mimetype", ""),
                digest=rec.get("digest", ""),
                length=rec.get("length", ""),
                urlkey=rec.get("urlkey", ""),
                redirect=rec.get("redirect", ""),
                source_query=source_query,
            )
        )
    return out


def cdx_data_rows(rows: list) -> int:
    """How many data rows a CDX json body carried, header excluded.

    `parse_cdx_json` drops rows that are after the cutoff or malformed, so the
    length of its output is *not* how full the page was. Paging decisions must
    use this count instead, or a page of rows that were all filtered out looks
    like the last page and turns an unfinished scan into a "complete" one.
    """
    if not rows:
        return 0
    first = rows[0]
    header = bool(first and isinstance(first[0], str) and first[0] in ("urlkey", "timestamp"))
    return max(0, len(rows) - (1 if header else 0))


def cdx_query(fetcher: Fetcher, url: str, *, match: str = "prefix", limit: int = 10000,
              extra: Optional[dict] = None) -> tuple[list[Capture], Response]:
    """One CDX query. Returns captures and the raw response for diagnostics."""
    params = {
        "url": url,
        "matchType": match,
        "from": "19960101",
        "to": config.CUTOFF,
        "fl": DEFAULT_FIELDS,
        "limit": str(limit),
    }
    if extra:
        params.update(extra)
    resp = fetcher.cdx(params)
    if not resp.ok:
        return [], resp
    try:
        rows = resp.json()
    except Exception as exc:  # pragma: no cover - defensive
        resp.error = "http_error"
        resp.message = f"bad cdx json: {exc}"
        return [], resp
    resp.cdx_rows = cdx_data_rows(rows)
    return parse_cdx_json(rows, source_query=url), resp


def cdx_query_multi(*_a, **_kw):
    """Removed on purpose: measured to answer only the *first* `url=` parameter.

    2026-10, `web.archive.org/cdx/search/cdx`: a request carrying two `url=`
    parameters returns rows for the first one only -- verified with both
    `matchType=prefix` and `matchType=exact`, and in both parameter orders.
    The API looks like it accepts a repeated `url=`, so a batched scan reads as
    working while silently reporting a *negative* for every stem after the
    first. That produced 1656 false "no capture" answers before it was caught,
    so there is deliberately no batch helper here: one question, one request.
    """
    raise NotImplementedError("multi-url CDX queries answer only the first url=")


def year_windows(start_year: int = 2007, end_year: int = 2019) -> list[str]:
    """Per-year `from` values so big inventories can resume after interruption."""
    return [f"{y}0101" for y in range(start_year, end_year + 1)]


class CaptureIndex:
    """Append-only JSONL capture inventory with a resumable manifest."""

    def __init__(self, path: str, manifest_path: str | None = None):
        self.path = path
        self.manifest_path = manifest_path or path + ".manifest.json"
        self._keys: set[str] = set()
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        if os.path.exists(path):
            with open(path, encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        rec = json.loads(line)
                    except Exception:
                        continue
                    self._keys.add(f"{rec.get('timestamp')}|{normalize_url(rec.get('original',''))}")
        self.manifest = self._load_manifest()

    def _load_manifest(self) -> dict:
        if os.path.exists(self.manifest_path):
            try:
                with open(self.manifest_path, encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                return {}
        return {"done": {}, "stats": {}}

    def save_manifest(self) -> None:
        tmp = self.manifest_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(self.manifest, fh, ensure_ascii=False, indent=2, sort_keys=True)
        os.replace(tmp, self.manifest_path)

    def query_done(self, name: str) -> bool:
        return bool(self.manifest.get("done", {}).get(name))

    def mark_done(self, name: str, info: dict | None = None) -> None:
        self.manifest.setdefault("done", {})[name] = info or {"at": _now()}
        # A successful (re)query supersedes an earlier failure record.
        self.manifest.get("failed", {}).pop(name, None)
        self.save_manifest()

    def mark_failed(self, name: str, info: dict | None = None) -> None:
        """Record a query that did *not* get an answer, without settling it.

"""Host-level media inventory for Tumblr CDN images.

Querying the CDX once per image is slow and mostly returns nothing: a Tumblr
post page references one size variant (`..._500.jpg`) while the archive often
holds a *different* variant of the same media file. Instead we inventory whole
`*.media.tumblr.com` hosts once (a few thousand rows, one request each with
`collapse=urlkey`) and match every known media key locally. Only images whose
key we actually reference are persisted, which keeps the committed inventory
small while still recording the capture that produced each recovered image.
"""
from __future__ import annotations

import json
import os
import re
from typing import Iterable, Optional

from . import config
from .cdx import Capture, CaptureIndex, cdx_query, normalize_url, within_cutoff
from .parsing import base_media_key, media_key, parse_image_variants

MEDIA_CAPTURE_FILE = os.path.join(config.CDX_DIR, "media.jsonl")
# Ephemeral per-run cache of whole-host CDX rows (gitignored, never required).
MEDIA_DUMP_DIR = os.path.join(config.DATA_DIR, "work", "media-dumps")
HOST_RE = re.compile(r"^([a-z0-9-]+(?:\.[a-z0-9-]+)*\.media\.tumblr\.com)$", re.I)


def _now() -> str:
    import datetime

    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")


def host_of(url: str) -> str:
    m = re.match(r"^https?://([^/]+)", url or "", re.I)
    return m.group(1).lower() if m else ""


def key_of(url: str) -> str:
    """Lowercase identity of a media file, ignoring size suffix and extension."""
    base = base_media_key(url) or media_key(url) or os.path.basename(normalize_url(url))
    base = base.lower()
    stem, _, ext = base.rpartition(".")
    return stem + "." + ext if ext else stem


def stems_of(url: str) -> set[str]:
    """Every key a media file could be indexed under (all size variants)."""
    keys = {key_of(v) for v in parse_image_variants(url)}
    keys.add(key_of(url))
    return {k for k in keys if k}


class MediaIndex:
    """Local, durable index of archived media captures keyed by media file."""

    def __init__(self, path: str = ""):
        # Late-bound on purpose: see PostStore.__init__ (import-time defaults
        # would pin the committed data/cdx/media.jsonl into every caller).
        self.index = CaptureIndex(path or os.path.join(config.CDX_DIR, "media.jsonl"))
        self._by_url: dict[str, list[Capture]] = {}
        self._by_key: dict[str, list[Capture]] = {}
        for cap in self.index.all():
            self._remember(cap)
        # Older runs wrote the manifest key as `host:host:<h>`, so every scan
        # looked unfinished and got re-requested from page 1 forever.
        self.hosts_done()

    def _remember(self, cap: Capture) -> None:
        self._by_url.setdefault(normalize_url(cap.original), []).append(cap)
        self._by_key.setdefault(key_of(cap.original), []).append(cap)

    def add(self, captures: Iterable[Capture]) -> int:
        caps = list(captures)
        new = self.index.add(caps)
        for cap in caps:
            self._remember(cap)
        return new

    def lookup(self, url: str) -> list[Capture]:
        """Captures for a media URL: exact match first, then any variant."""
        exact = self._by_url.get(normalize_url(url), [])
        if exact:
            return sorted(exact, key=lambda c: c.timestamp)
        out: list[Capture] = []
        for key in stems_of(url):
            out.extend(self._by_key.get(key, []))
        # Same media file on another CDN host is still evidence of the image.
        if not out:
            for key in stems_of(url):
                for cap_url, caps in self._by_key.items():
                    if key in cap_url:
                        out.extend(caps)
        seen: set[str] = set()
        uniq = []
        for cap in sorted(out, key=lambda c: c.timestamp):
            if cap.key in seen:
                continue
            seen.add(cap.key)
            uniq.append(cap)
        return uniq

    def __len__(self) -> int:
        return len(self.index.all())

    def hosts_done(self) -> dict:
        """Manifest `done` map, with legacy `host:host:<h>` keys repaired.

        The repair matters for more than tidiness: a host whose scan reached its
        last page is *positive evidence* that its pre-cutoff 200 rows have all
        been seen. With the key spelled wrongly that evidence was invisible, so
        every run re-downloaded completed hosts (archive load) and never let the
        crawler record a confirmed per-host gap.
        """
        done = self.index.manifest.setdefault("done", {})
        stale = [k for k in done if k.startswith("host:host:")]
        for key in stale:
            done[key[len("host:"):]] = done.pop(key)
        if stale:
            self.index.save_manifest()

