python3 - <<'EOF'
import json,glob,os,re
hits={}
for line in open('data/cdx/stems.jsonl'):
    line=line.strip()
    if not line: continue
    try: r=json.loads(line)
    except: continue
    caps=r.get('captures') or []
    if caps: hits[r['stem']]=caps
def fstem(s):
    # path after md5dir
    m=re.search(r'/(tumblr_[^/]+)$', s)
    return m.group(1) if m else s
rec=set(); missing={}
for f in glob.glob('data/posts/*.json'):
    try: d=json.load(open(f))
    except: continue
    pid=os.path.basename(f)[:-5]
    for im in d.get('images') or []:
        keys=[im.get(k) for k in ('media_key','base_key','file') if im.get(k)]
        # also derive from url_forms/variants
        for u in (im.get('url_forms') or [])[:1]+(im.get('variants') or [])[:1]:
            keys.append(os.path.basename(u))
        if im.get('sha256'):
            for k in keys: rec.add(fstem(k))
        else:
            for k in keys: missing.setdefault(fstem(k),(pid,im.get('media_url') or (im.get('variants') or [''])[0]))
un=[]
for s,caps in hits.items():
    b=fstem(s)
    if b in rec: continue
    un.append((s,b,caps,missing.get(b)))
print('unretrieved',len(un))
for s,b,caps,m in un:
    print(b, 'missing_owner=',m, [ (x.get('timestamp'), x.get('original')) for x in caps][:2])
EOF

python3 - <<'EOF'
import json,glob,os,re
hits={}
for line in open('data/cdx/stems.jsonl'):
    line=line.strip()
    if not line: continue
    try: r=json.loads(line)
    except: continue
    caps=r.get('captures') or []
    if caps: hits[r['stem']]=caps
def norm(b):
    b=os.path.basename(b)
    return re.sub(r'_\d+\.(jpg|png|gif)$','',b,flags=re.I)
rec=set(); missing={}
for f in glob.glob('data/posts/*.json'):
    try: d=json.load(open(f))
    except: continue
    pid=os.path.basename(f)[:-5]
    for im in d.get('images') or []:
        keys=set()
        for k in ('media_key','base_key','file'):
            if im.get(k): keys.add(norm(im[k]))
        for u in (im.get('url_forms') or [])+(im.get('variants') or []):
            keys.add(norm(u))
        if im.get('sha256'):
            rec|=keys
        else:
            for k in keys:
                if k not in missing: missing[k]=(pid,im.get('media_url') or (im.get('variants') or [''])[0])
un=[]
for s,caps in hits.items():
    b=norm(s)
    if b in rec: continue
    un.append((s,b,caps,missing.get(b)))
print('unretrieved stem hits:',len(un))
for s,b,caps,m in un:
    print(b,'owner=',m and m[0], [ (x.get('timestamp'), x.get('original')) for x in caps][:1])
EOF

