def reindex_media(hosts: Optional[list[str]] = None) -> dict:
    """Rebuild the committed media index from surviving host dumps (no network).

    Newly parsed posts bring new media keys; when a host dump from earlier in
    the run is still on disk the new keys can be answered without new CDX
    requests.
    """
    store = PostStore()
    urls = [img.get("media_url", "") for rec in store.all() for img in rec.get("images", [])]
    keys: set[str] = set()
    for url in urls:
        keys |= stems_of(url)
    targets = hosts or hosts_for(urls)
    index = MediaIndex(capture_file("media.jsonl"))
    results = []
    for host in targets:
        state = index.hosts_done().get(f"host:{host}") or {}
        if not state.get("complete"):
            results.append({"host": host, "skipped": "not fully scanned"})
            continue
        results.append(scan_host(None, index, host, keys=keys, force=False))
    return {"hosts": len(targets), "known_keys": len(keys), "indexed": len(index),
            "results": results}

def xshard_scan(fetcher: Fetcher, *, hosts: Optional[list[str]] = None,
                limit: int = 2000, rescan: bool = False,
                apply: bool = True) -> dict:
    hosts = hosts or list(DEFAULT_HOSTS)
    state = _load_host_state()
    store = PostStore() if apply else None
    out = {"hosts": [], "requests_sent": 0, "found": 0, "applied": 0,
           "scanned": 0, "skipped_done": 0, "failed": 0}
    for host in hosts:
        prev = state.get(host) or {}
        if prev.get("done") and not rescan:
            out["skipped_done"] += 1
            continue
        caps, diag = scan_host(fetcher, host, limit=limit)
        out["requests_sent"] += 1
        out["scanned"] += 1
        if diag.get("error"):
            out["failed"] += 1
            state[host] = {"done": False, "error": diag.get("error"),
                           "status": diag.get("status"), "at": _now()}
            out["hosts"].append(diag)
            _save_host_state(state)
            continue
        append_found(caps, {"host": host})
        out["found"] += len(caps)
        applied = apply_captures(store, caps) if apply else {"added_forms": 0}
        out["applied"] += applied.get("added_forms", 0)
        state[host] = {"done": True, "rows": len(caps), "at": _now(),
                       "applied": applied.get("added_forms", 0)}
        out["hosts"].append({**diag, "applied": applied})
        _save_host_state(state)
    out["pending_hosts"] = [h for h in hosts if not (state.get(h) or {}).get("done")]
    return out


def _now() -> str:
    import time
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

