import json,glob,re,collections,time,os
from recovery.http import Fetcher
from recovery.images import stem_prefix
from recovery.cli import fetch_posts
from recovery.store import PostStore
from recovery.stemindex import StemIndex

inv=collections.defaultdict(set)
for l in open('data/cdx/posts.jsonl'):
    r=json.loads(l)
    u=r.get('original') or r.get('url') or ''
    m=re.search(r'/post/(\d+)',u)
    if not m: continue
    inv[m.group(1)].add(r.get('timestamp'))
store=PostStore()
si=StemIndex()
cands=[]
for p in glob.glob('data/posts/*.json'):
    r=json.load(open(p))
    pid=str(r.get('post_id'))
    rep={a.get('capture_timestamp') for a in r.get('methods') or [] if a.get('capture_timestamp')}
    pend=[t for t in inv.get(pid,set()) if t not in rep]
    if pend:
        cands.append((len(pend), pid))
cands.sort(key=lambda x:(x[0], int(x[1])))
ids=[pid for _,pid in cands]
print("total posts with pending captures:", len(ids), "captures:", sum(n for n,_ in cands), flush=True)

def stems_now():
    d={}
    for pid in ids:
        r=store.get(pid) or {}
        forms=set()
        for im in r.get('images') or []:
            for u in (im.get('url_forms') or [])+[im.get('media_url')]:
                if u: forms.add(u)
        d[pid]={stem_prefix(u) for u in forms}
    return d
before=stems_now()
f=Fetcher(timeout=40, attempts=2)
t0=time.time()
CH=80
newstems=set()
processed=0
for i in range(0,len(ids),CH):
    chunk=ids[i:i+CH]
    res=fetch_posts(f, limit=len(chunk), post_ids=chunk, concurrency=1)
    processed+=len(chunk)
    after=stems_now() if False else None
    # incremental: just diff chunk
    for pid in chunk:
        r=store.get(pid) or {}
        forms=set()
        for im in r.get('images') or []:
            for u in (im.get('url_forms') or [])+[im.get('media_url')]:
                if u: forms.add(u)
        st={stem_prefix(u) for u in forms}
        newstems |= (st - before.get(pid,set()))
    print(f"  chunk {i//CH+1} done processed={processed}/{len(ids)} elapsed={time.time()-t0:.0f}s newstems_so_far={len(newstems)}", flush=True)
    if time.time()-t0>1100: 
        print("time budget reached, stopping", flush=True); break
print("TOTAL new stems:", len(newstems))
unasked=[s for s in newstems if not si.has(s)]
print("unasked among them:", len(unasked))
os.makedirs('data/cdx',exist_ok=True)
with open('data/cdx/new-stems-pending-captures.jsonl','w') as fh:
    for s in sorted(newstems):
        fh.write(json.dumps({"stem":s,"unasked":(not si.has(s))})+"\n")
for s in sorted(newstems)[:60]: print("   ",s)
EOF

