import json,glob,re,collections
# recovered media names
rec=set()
for f in glob.glob('data/verification/*.json'):
    r=json.load(open(f))
    for c in r.get('checks',[]):
        m=re.match(r'image_size\[(.+)\]$',c.get('check',''))
        if m: rec.add(m.group(1))
def base(n):
    return re.sub(r'_\d+(\.[A-Za-z0-9]+)?$','',n)
recbases=set(base(n) for n in rec)
# last record per key
last={}
for l in open('data/missing.jsonl'):
    l=l.strip()
    if not l: continue
    r=json.loads(l)
    if r.get('kind')!='image': continue
    last[r.get('key')]=r
print("distinct image keys in missing",len(last))
byreason=collections.defaultdict(list)
for k,r in last.items():
    byreason[r.get('reason')].append((k,r))
for reason,items in sorted(byreason.items(),key=lambda x:-len(x[1])):
    print(reason,len(items))
# unresolved non-gap
unres=[]
for reason in ('throttled','transport','http_error','bad_body','timeout','unknown','capture_after_cutoff'):
    for k,r in byreason.get(reason,[]):
        mk=r.get('media_key','')
        b=base(mk)
        if b in recbases:  # alias of recovered
            continue
        unres.append((reason,k,mk,b))
print("unresolved (non-gap, not alias of recovered):",len(unres))
# cross-ref stems with captures
stems={}
for l in open('data/cdx/stems.jsonl'):
    l=l.strip()
    if not l: continue
    r=json.loads(l)
    if r.get('captures'):
        stems[r['key']]=r['captures']
print("stems with captures",len(stems))
def stemkey(mk):
    # strip _<size>.<ext> and trailing _rN
    s=re.sub(r'_\d+(\.[A-Za-z0-9]+)?$','',mk)
    return s
hits=[]
for reason,k,mk,b in unres:
    sk=stemkey(mk)
    # try both with and without host: stemkey has no host; match on path suffix
    for hostpath,caps in stems.items():
        if hostpath.endswith('/'+sk) or hostpath.split('/',1)[-1].endswith(sk):
            hits.append((reason,k,mk,caps))
            break
print("unresolved whose stem has captures:",len(hits))
for reason,k,mk,caps in hits[:30]:
    print(reason,k,"->",caps[0]['original'],caps[0]['timestamp'],caps[0].get('length'))
EOF

